<?php use App\Core\Csrf;$v=fn($k)=>$input[$k]??$event[$k]??'';$editing=(bool)$event;$dt=fn($x)=>$x?date('Y-m-d\TH:i',strtotime($x)):''; ?>
<div class="page-heading"><div><p class="eyebrow">Event management</p><h1><?=$editing?'Edit event':'Create event'?></h1></div><a class="button" href="<?=e(url('/events'))?>">Cancel</a></div><?php if($errors):?><div class="alert danger"><?=e($errors['form']??implode(' ',array_values($errors)))?></div><?php endif;?><form class="stack-form" method="post" action="<?=e($editing?url('/events/'.$event['id']):url('/events'))?>"><?=Csrf::field()?><section class="card form-section"><h2>Event details</h2><label>Title<input required name="title" value="<?=e($v('title'))?>"></label><label>Description<textarea name="description" rows="5"><?=e($v('description'))?></textarea></label><div class="grid two"><label>Venue<input name="venue" value="<?=e($v('venue'))?>"></label><label>Capacity<input type="number" min="1" name="capacity" value="<?=e((string)$v('capacity'))?>"></label></div></section><section class="card form-section"><h2>Schedule and access</h2><div class="grid two"><label>Starts<input required type="datetime-local" name="starts_at" value="<?=e($input['starts_at']??$dt($event['starts_at']??null))?>"></label><label>Ends<input required type="datetime-local" name="ends_at" value="<?=e($input['ends_at']??$dt($event['ends_at']??null))?>"></label><label>Visibility<select name="visibility"><?php foreach(['all','students','teachers','staff','invited'] as $x):?><option value="<?=$x?>" <?=$v('visibility')===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select></label><label>Status<select name="status"><?php foreach(['draft','published','ongoing','completed','cancelled'] as $x):?><option value="<?=$x?>" <?=$v('status')===$x?'selected':''?>><?=e(ucfirst($x))?></option><?php endforeach;?></select></label></div></section><div class="sticky-actions"><button class="button primary">Save event</button></div></form>
